/**
 * ExplanationPanel.jsx — LLM Reasoning Display
 * ================================================
 * Shows the plain-English explanation generated by the LLM.
 * Includes a subtle typewriter-style reveal animation.
 */

import { useState, useEffect } from 'react';
import { useApi } from '../hooks/useApi';
import { getExplanation } from '../services/api';

export default function ExplanationPanel({ ticker }) {
  const { data, loading, error } = useApi(getExplanation, ticker);
  const [displayText, setDisplayText] = useState('');
  const [isAnimating, setIsAnimating] = useState(false);

  const explanation = data?.explanation || '';

  // Typewriter animation effect
  useEffect(() => {
    if (!explanation) return;

    setIsAnimating(true);
    setDisplayText('');
    let index = 0;

    const interval = setInterval(() => {
      if (index < explanation.length) {
        setDisplayText(explanation.slice(0, index + 1));
        index++;
      } else {
        clearInterval(interval);
        setIsAnimating(false);
      }
    }, 12); // speed: 12ms per character

    return () => clearInterval(interval);
  }, [explanation]);

  if (loading) {
    return (
      <div className="glass-card explanation-panel">
        <div className="section-title">
          <span className="section-title__dot" />
          AI Reasoning
        </div>
        <div className="skeleton skeleton--text" style={{ width: '100%' }} />
        <div className="skeleton skeleton--text" style={{ width: '90%' }} />
        <div className="skeleton skeleton--text" style={{ width: '70%' }} />
      </div>
    );
  }

  // Get prediction info from the response
  const prediction = data?.prediction;
  const headlines = data?.headlines_used || [];

  return (
    <div className="glass-card explanation-panel fade-in">
      <div className="section-title">
        <span className="section-title__dot" />
        AI Reasoning — {ticker}
      </div>

      {/* Prediction badge */}
      {prediction && (
        <div style={{ marginBottom: '1rem' }}>
          <span className={`signal-badge signal-badge--${prediction.signal?.toLowerCase()}`}>
            {prediction.signal === 'UP' ? '▲' : '▼'} Predicts {prediction.signal}
            {prediction.confidence && ` (${(prediction.confidence * 100).toFixed(0)}%)`}
          </span>
        </div>
      )}

      {/* LLM Explanation Text */}
      <div className="explanation-panel__text">
        {error ? (
          <span style={{ color: 'var(--color-warning)' }}>
            ⚠ Could not load explanation: {error}
          </span>
        ) : (
          <>
            {displayText}
            {isAnimating && (
              <span style={{
                display: 'inline-block',
                width: '2px',
                height: '1em',
                background: 'var(--text-accent)',
                marginLeft: '2px',
                animation: 'blink 0.8s infinite',
                verticalAlign: 'text-bottom',
              }} />
            )}
          </>
        )}
      </div>

      {/* Recent Headlines Used */}
      {headlines.length > 0 && (
        <div style={{ marginTop: '1.25rem' }}>
          <div style={{
            fontSize: '0.75rem',
            color: 'var(--text-muted)',
            textTransform: 'uppercase',
            letterSpacing: '0.05em',
            marginBottom: '0.5rem',
          }}>
            Headlines Considered
          </div>
          {headlines.slice(0, 3).map((h, i) => (
            <div key={i} style={{
              fontSize: '0.8rem',
              color: 'var(--text-secondary)',
              padding: '0.35rem 0',
              borderBottom: i < 2 ? '1px solid var(--border-subtle)' : 'none',
            }}>
              "{h.length > 100 ? h.slice(0, 100) + '...' : h}"
            </div>
          ))}
        </div>
      )}


      {/* Blink keyframe (inline, needed for cursor) */}
      <style>{`
        @keyframes blink {
          0%, 50% { opacity: 1; }
          51%, 100% { opacity: 0; }
        }
      `}</style>
    </div>
  );
}
